/* -------------------------------------------------------------------------- */
/*                  Animated Julia Sets with color gradient                   */
/*                                                                            */
/* uses neat trick to estimate distance but is unreliable inside the set      */
/* using n and length of z_n for color is visually more impressive anyway     */
/* -------------------------------------------------------------------------- */

const float LOOP_DURATION = 15.0; // in seconds
const float ITERATIONS = 256.0;


const float PI  = 3.1415927;
const float TAU = 6.2831855;

/* ------------------------- COLOR HELPER FUNCTIONS ------------------------- */


vec3 palette( in float t )
{
    vec3 a = vec3(0.5, 0.5, 0.5);
    vec3 b = vec3(0.5, 0.5, 0.5);
    vec3 c = vec3(1.0, 1.0, 1.0);
    vec3 d = vec3(0.0, 0.1, 0.2);
    return a + b*cos( TAU*(c*t+d) );
}

vec3 gradient2col( in float a )
{
    vec3 firstColor = vec3(1.0,0.0,0.0); //red
    vec3 endColor = vec3(0.0,0.0,1.0); // blue
    return mix(firstColor, endColor, a);
}

vec3 gradient3col( in float a )
{
    vec3 firstColor = vec3(0.199999, 0.0, 0.333333);   // Dark Purple
    vec3 middleColor = vec3(1.0, 0.333333, 0.333333);  // Light Red
    vec3 endColor = vec3(1.0, 0.833333, 0.666666);     // Very Light Orange

    float h = 0.5; // adjust position of middleColor

    return mix(mix(firstColor, middleColor, a/h), mix(middleColor, endColor, (a - h)/(1.0 - h)), step(h, a));
}


/* ----------------------- COMPLEX NUMBER OPERATIONS ------------------------ */


vec2 complexMul( in vec2 a, in vec2 b )
{
    return vec2(a.x * b.x - a.y * b.y, a.x * b.y + a.y * b.x);
}

vec2 complexSqr( in vec2 z )
{
    return vec2(z.x * z.x - z.y * z.y, 2.0 * z.x * z.y);
}


/* --------------------- MAIN FRAGMENT SHADER FUNCTION ---------------------- */


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates and fix stretched pixels (from -1 to 1)
    vec2 UV = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;
    // iTime is only used in sin()/cos() so a full loop is their period 2pi
    // change the period to given loop duration
    float scaledTime = (iTime * TAU / LOOP_DURATION) - PI;


    /* ---------------------- JULIA SET ITERATION PART ---------------------- */


    // Julia Set constant c cycling by time
    vec2 c = vec2(0.7885) * vec2(cos(scaledTime), sin(scaledTime));

    // z0 starts with uv coordinate as complex number
    vec2 z = UV;
    // z length squared
    float zLenSqr = dot(z, z);
    // derivative z length squared
    float dLenSqr = 1.0;
    // remember where i stopped to check if we're outside/inside the set
    // also used for color calculation later if outside set
    float i;

    // iterating Julia Set zn+1 = zn^2 + c
    for(i = 0.0; i < ITERATIONS; i++)
    {
        // simplification |z'n+1|^2 = 4 * |zn|^2 * |z'n|^2
        dLenSqr = 4.0 * zLenSqr * dLenSqr;

        // Julia iteration step
        z = complexSqr(z) + c;

        // if current z length squared is massive we break early
        // because it's diverging to infinity (meaning outside the set)
        zLenSqr = dot(z, z);
        if (zLenSqr > 1e10) break;
    }


    /* ----------------------- CALCULATING COLOR PART ----------------------- */


    // clever distance estimation using derivative z'n but unreliable inside set
    float estimatedDist = sqrt(zLenSqr / dLenSqr) * 0.5 * log(zLenSqr);
    // un-comment these two lines if you want to see it used
    //fragColor = vec4(palette(estimatedDist), 1.0);
    //return;


    // visually better results with last zLenSqr and i values after break;


    // start with black for inside set
    vec3 col = vec3(0.0);

    // if outside Julia Set replace black with color gradient
    if (i < ITERATIONS)
    {
        // offset i by +2 removes ugly gradient border near the image edges
        //col = vec3(1.0-fract(20.0*(i + 2.0 - log2(log2(sqrt(zLenSqr))))/ITERATIONS));
        // previous line expanded for readability and debugging 
        float colVal = zLenSqr;
        colVal = sqrt(colVal);
        colVal = log2(colVal);
        colVal = log2(colVal);
        colVal = (i + 2.0 - colVal) / ITERATIONS;
        colVal = 16.0 * colVal;
        colVal = fract(colVal);

        // black to white to visually debug colVal as lerp factor for gradient
        // but inverted since black is already inside the set
        //col = vec3(1.0 - colVal);  

        // palette function cycles seamlessly removing gradient borders
        //col = palette(colVal);

        // so we use a linear interpolated 3 color gradient instead
        col = gradient3col(colVal);
    }

    // output to screen
    fragColor = vec4(col, 1.0);
}
